import json

def read_value_field(file_path):
    with open(file_path, 'r') as file:
        data = json.load(file)
    return data['value']

def print_exact_value(value):
    print(f"Value: {value}")

def main():
    file_path = '/world.json'
    probe_value = read_value_field(file_path)
    print_exact_value(probe_value)

if __name__ == "__main__":
    main()

